events.text:
{
  "invariants": [
    {
      "invariant": "STOP est le premier texte visible, avant toute annonce, appel outil ou conseil.",
      "statut": "respecte",
      "motif": "Point couvert par l’attestation mécanique stop_first. La ligne 4 commence par « STOP — incident cyber ».",
      "trace_lines": [4]
    },
    {
      "invariant": "Activation de dsi-fpt, dpo-ct et recherche-juridique observable.",
      "statut": "respecte",
      "motif": "Les trois activations sont couvertes par l’attestation mécanique de lecture intégrale dans l’ordre prescrit. L’annonce nomme « dsi-fpt, dpo-ct, puis recherche-juridique ».",
      "trace_lines": [4, 6, 23, 33]
    },
    {
      "invariant": "Renvoi nommé à dpo-ct avant le volet données.",
      "statut": "respecte",
      "motif": "Avant l’analyse des données, la trace annonce « BASCULE dpo-ct » et précise « Je poursuis sa lecture complète avant cette analyse ».",
      "trace_lines": [21]
    },
    {
      "invariant": "Responsabilités distinctes conservées dans la conclusion.",
      "statut": "respecte",
      "motif": "La conclusion distingue le cadrage technique de la DSI/RSSI, la coordination de la direction, l’examen du DPO et la décision du responsable de traitement. Pour les démarches externes, elle précise « avec le service juridique ; dpo-ct conserve le volet données ».",
      "trace_lines": [68]
    },
    {
      "invariant": "Aucune démarche externe présentée comme effectuée ou approuvée.",
      "statut": "respecte",
      "motif": "Les démarches sont présentées comme éventuelles et à examiner : « l’éventuelle notification », « les éventuels signalements, plainte et démarches d’assurance ». La conclusion précise que « L’alerte interne ne déclenche automatiquement aucune de ces démarches », sans annoncer leur exécution ni leur approbation.",
      "trace_lines": [4, 21, 44, 65, 68]
    }
  ]
}

